entries[10007] = { ["name"] = "Phantomklinge", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (28), Odem des Windes (6), Echtsilberbarren (8), Geringer Unsichtbarkeitstrank (2), Aquamarin (6), Robuster Schleifstein (4), Dickes Leder (2)\nPhantomklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n59 - 111 Schaden Tempo 2.60\n(32.69 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n44\nTrefferchance: Verringert die Rüstung des Ziels 20 Sek. lang um 100. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[10009] = { ["name"] = "Runenverzierter Mithrilhammer", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (18), Erdenkern (2), Robuster Schleifstein , Dickes Leder (4)\nRunenverzierter Mithrilhammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n41 - 76 Schaden Tempo 2.00\n(29.25 Schaden pro Sekunde)\n+7 Stärke\n+4 Ausdauer\nHaltbarkeit 75 / 75\n44" }
entries[10011] = { ["name"] = "Verseuchung", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (28), Sekret des Untodes (10), Echtsilberbarren (10), Robuster Schleifstein (6), Dickes Leder (6)\nVerseuchung\nWird beim Anlegen gebunden\nZweihändig Stangenwaffe\n128 - 193 Schaden Tempo 3.70\n(43.38 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\n45\nTrefferchance: Lässt ein Ziel erkranken und fügt so im Verlauf von 10 Sek. 50 Naturschaden sowie insgesamt 50 zusätzlichen Schaden zu." }
