entries[11185] = { ["name"] = "Eissplitter", ["text"] = "Fügt Eurem Zauber 'Blizzard' einen Kälteeffekt hinzu. Dieser Effekt verringert das Bewegungstempo des Ziels um 25%. Hält 2 Sek. lang an. Zudem wird die Reichweite Eures Zaubers 'Eislanze' um 2 Meter erhöht." }
