entries[11210] = { ["name"] = "Verbesserte Verwandlung", ["text"] = "Wenn ein von Euch verwandeltes Ziel Schaden erleidet, wird es 1.5 Sek. lang betäubt. Dieser Effekt kann nur ein Mal alle 10 Sek. auftreten." }
entries[11213] = { ["name"] = "Arkane Konzentration", ["text"] = "Gewährt Euch eine Chance von 3%, in einen Freizauberzustand zu gelangen, nachdem einer Eurer Schadenszauber ein Ziel getroffen hat. Der Freizauberzustand verringert die Manakosten Eures nächsten Schadenszaubers um 100%.\n(Procchance: 13%, 15s Abklingzeit)" }
entries[11222] = { ["name"] = "Arkaner Fokus", ["text"] = "Wird einem von Euch gewirkten Zauber widerstanden, werden Euch 25% der Manakosten dieses Zaubers zurückerstattet." }
entries[11232] = { ["name"] = "Arkaner Geist", ["text"] = "Erhöht Eure gesamte Intelligenz um 2%." }
entries[11237] = { ["name"] = "Arkane Stabilität", ["text"] = "Verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von 'Arkanschlag' oder die Zauberzeitverringerung beim Kanalisieren von 'Arkane Geschosse' um 50%." }
entries[11242] = { ["name"] = "Zaubereinschlag", ["text"] = "Erhöht den Schaden Eurer Zauber 'Arkane Explosion', 'Arkanschlag', 'Druckwelle', 'Feuerschlag', 'Versengen', 'Feuerball', 'Eislanze' und 'Kältekegel' um zusätzliche 2%." }
