entries[11426] = { ["name"] = "Eisbarriere", ["text"] = "21% von Grundmana\nSofort 30 sek. Abklingzeit\nSchirmt Euch sofort ab und absorbiert [( 8285 + Spell power * 0.87)] Schaden. Hält 1 Min. lang an. Solange der Schild hält, werden Zauber durch erlittenen Schaden nicht verzögert." }
