entries[11438] = { ["name"] = "Kartenfragmente zusammenfügen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nOberes Kartenfragment , Unteres Kartenfragment , Mittleres Kartenfragment\nFügt das untere, das mittlere und das obere Kartenfragment zusammen." }
